// Procedural textures: every pixel is generated by this code (no external assets).
import * as THREE from 'three';
import { rng, vnoise, fbm, clamp, TAU } from './util.js';

export function cv(w, h) { const c = document.createElement('canvas'); c.width = w; c.height = h; return c; }

export function mkTex(canvas, o = {}) {
  const t = new THREE.CanvasTexture(canvas);
  t.colorSpace = o.data ? THREE.NoColorSpace : THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = o.clampEdge ? THREE.ClampToEdgeWrapping : THREE.RepeatWrapping;
  if (o.repeat) t.repeat.set(o.repeat[0], o.repeat[1]);
  t.anisotropy = o.aniso || 4;
  t.needsUpdate = true;
  return t;
}

// height(x,y) -> [0,1]; returns normal map canvas (tileable if height is)
export function normalFrom(w, h, height, strength = 2) {
  const c = cv(w, h), g = c.getContext('2d'), im = g.createImageData(w, h), d = im.data;
  const H = new Float32Array(w * h);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) H[y * w + x] = height(x, y);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const l = H[y * w + ((x + w - 1) % w)], r = H[y * w + ((x + 1) % w)];
    const u = H[((y + h - 1) % h) * w + x], dn = H[((y + 1) % h) * w + x];
    let nx = (l - r) * strength, ny = (dn - u) * strength, nz = 1;
    const il = 1 / Math.hypot(nx, ny, nz); nx *= il; ny *= il; nz *= il;
    const i = (y * w + x) * 4;
    d[i] = (nx * 0.5 + 0.5) * 255; d[i + 1] = (ny * 0.5 + 0.5) * 255; d[i + 2] = (nz * 0.5 + 0.5) * 255; d[i + 3] = 255;
  }
  g.putImageData(im, 0, 0);
  return c;
}

function grainNoise(g, w, h, alpha, seed, mono = true) {
  const im = g.getImageData(0, 0, w, h), d = im.data, r = rng(seed);
  for (let i = 0; i < d.length; i += 4) {
    const n = (r() - 0.5) * 255 * alpha;
    d[i] = clamp(d[i] + n, 0, 255); d[i + 1] = clamp(d[i + 1] + (mono ? n : (r() - 0.5) * 255 * alpha), 0, 255); d[i + 2] = clamp(d[i + 2] + (mono ? n : (r() - 0.5) * 255 * alpha), 0, 255);
  }
  g.putImageData(im, 0, 0);
}

// ---------- wood ----------
export function woodPlanks(o = {}) {
  const W = 1024, H = 1024, c = cv(W, H), g = c.getContext('2d'), r = rng(o.seed || 5);
  const rows = o.rows || 8, base = o.base || [196, 158, 112], ph = H / rows;
  const hc = cv(W, H), hg = hc.getContext('2d'); hg.fillStyle = '#808080'; hg.fillRect(0, 0, W, H);
  for (let i = 0; i < rows; i++) {
    const off = r() * W, split = 0.4 + r() * 0.2;
    for (let k = -1; k < 2; k++) for (let part = 0; part < 2; part++) {
      const x0 = off + k * W + (part ? split * W : 0), len = (part ? 1 - split : split) * W;
      const rr = rng((o.seed || 5) * 131 + i * 7 + part);
      const t = 0.86 + rr() * 0.24, warm = (rr() - 0.5) * 14;
      g.fillStyle = `rgb(${base[0] * t + warm | 0},${base[1] * t | 0},${base[2] * t - warm | 0})`;
      g.fillRect(x0, i * ph, len + 2, ph);
      g.save(); g.beginPath(); g.rect(x0, i * ph, len, ph); g.clip();
      for (let s = 0; s < 70; s++) {
        const yy = i * ph + rr() * ph, a = 0.03 + rr() * 0.07;
        g.strokeStyle = rr() < 0.6 ? `rgba(90,60,30,${a})` : `rgba(255,235,200,${a})`;
        g.lineWidth = 0.6 + rr() * 1.6; g.beginPath(); g.moveTo(x0, yy);
        const wob = (rr() - 0.5) * 8;
        g.bezierCurveTo(x0 + len * 0.3, yy + wob, x0 + len * 0.6, yy - wob, x0 + len, yy + (rr() - 0.5) * 6); g.stroke();
      }
      if (rr() < 0.5) { // knot / cathedral grain
        const kx = x0 + rr() * len, ky = i * ph + ph * (0.3 + rr() * 0.4);
        for (let q = 0; q < 6; q++) { g.strokeStyle = `rgba(80,50,25,${0.06})`; g.lineWidth = 1; g.beginPath(); g.ellipse(kx, ky, 18 + q * 9, 3 + q * 2.2, 0, 0, TAU); g.stroke(); }
      }
      g.restore();
      g.fillStyle = 'rgba(40,25,10,0.5)'; g.fillRect(x0 - 1, i * ph, 2, ph);
      hg.fillStyle = '#303030'; hg.fillRect(x0 - 1.5, i * ph, 3, ph);
    }
    g.fillStyle = 'rgba(40,25,10,0.55)'; g.fillRect(0, i * ph - 1, W, 2); if (i === 0) g.fillRect(0, H - 1, W, 1);
    hg.fillStyle = '#303030'; hg.fillRect(0, i * ph - 1.5, W, 3); if (i === 0) hg.fillRect(0, H - 1.5, W, 1.5);
  }
  grainNoise(g, W, H, 0.035, 11);
  const hd = hg.getImageData(0, 0, W, H).data;
  const nrm = normalFrom(W, H, (x, y) => hd[(y * W + x) * 4] / 255 + fbm(x / 6, y / 60, 16, 3, 3) * 0.12, 1.6);
  const rep = o.repeat || [4, 4];
  return { map: mkTex(c, { repeat: rep, aniso: 8 }), normalMap: mkTex(nrm, { repeat: rep, data: true, aniso: 8 }) };
}

export function woodPlain(base = [205, 170, 125], seed = 9) {
  const W = 512, H = 512, c = cv(W, H), g = c.getContext('2d'), r = rng(seed);
  g.fillStyle = `rgb(${base})`; g.fillRect(0, 0, W, H);
  for (let s = 0; s < 260; s++) {
    const yy = r() * H, a = 0.03 + r() * 0.06;
    g.strokeStyle = r() < 0.6 ? `rgba(95,62,30,${a})` : `rgba(255,240,210,${a})`;
    g.lineWidth = 0.6 + r() * 2; g.beginPath(); g.moveTo(0, yy);
    const wob = (r() - 0.5) * 14;
    g.bezierCurveTo(W * 0.3, yy + wob, W * 0.6, yy - wob, W, yy); g.stroke();
  }
  grainNoise(g, W, H, 0.03, seed + 1);
  return mkTex(c, { aniso: 8 });
}

// ---------- generic noise normals ----------
export function noiseNormal(size, scale, strength, seed = 1, oct = 3) {
  return mkTex(normalFrom(size, size, (x, y) => fbm(x / scale, y / scale, size / scale, oct, seed), strength), { data: true });
}

export function weaveNormal() { // plain cotton weave
  const S = 128;
  return mkTex(normalFrom(S, S, (x, y) => {
    const u = x / S * 16 * TAU, v = y / S * 16 * TAU;
    const warp = Math.sin(u) * 0.5 + 0.5, weft = Math.sin(v) * 0.5 + 0.5;
    const over = ((Math.floor(x / S * 16) + Math.floor(y / S * 16)) & 1) ? warp : weft;
    return over * 0.8 + vnoise(x / 3, y / 3, S / 3, 4) * 0.25;
  }, 1.5), { data: true });
}
export function jerseyNormal() { // knit T-shirt jersey: tiny V columns
  const S = 128;
  return mkTex(normalFrom(S, S, (x, y) => {
    const cx = (x / S * 24) % 1, cy = y / S * 24;
    const v = Math.abs(((cy + Math.abs(cx - 0.5) * 1.2) % 1) - 0.5) * 2;
    return v * 0.6 + Math.sin(cx * Math.PI) * 0.5 + vnoise(x / 2, y / 2, S / 2, 8) * 0.15;
  }, 1.4), { data: true });
}
export function terryNormal() { // towel loops
  const S = 256;
  return mkTex(normalFrom(S, S, (x, y) => {
    const a = vnoise(x / 2.2, y / 2.2, S / 2.2, 21), b = vnoise(x / 5, y / 5, S / 5, 22);
    return Math.pow(a, 1.5) * 0.9 + b * 0.35;
  }, 3.2), { data: true });
}
export function ribNormal() { // sock / sweater rib
  const S = 128;
  return mkTex(normalFrom(S, S, (x, y) => {
    const u = x / S * 12;
    return Math.pow(Math.abs(Math.sin(u * Math.PI)), 0.6) * 0.9 + vnoise(x / 2, y / 2, S / 2, 5) * 0.2;
  }, 2.4), { data: true });
}
export function feltNormal() {
  const S = 256;
  return mkTex(normalFrom(S, S, (x, y) => fbm(x / 3, y / 3, S / 3, 3, 31) * 0.7 + fbm(x / 24, y / 24, S / 24, 2, 32) * 0.5, 2.2), { data: true });
}

// ---------- strawberry motif ----------
function strawberry(g, x, y, s, rot, tone = 1) {
  g.save(); g.translate(x, y); g.rotate(rot); g.scale(s, s);
  const gr = g.createRadialGradient(-0.18, -0.15, 0.05, 0, 0.05, 1.05);
  gr.addColorStop(0, `rgb(${238 * tone | 0},${72 * tone | 0},${66 * tone | 0})`);
  gr.addColorStop(1, `rgb(${196 * tone | 0},${32 * tone | 0},${44 * tone | 0})`);
  g.fillStyle = gr;
  g.beginPath(); g.moveTo(0, 1.0);
  g.bezierCurveTo(-0.55, 0.62, -0.95, 0.05, -0.72, -0.42);
  g.bezierCurveTo(-0.55, -0.74, -0.15, -0.7, 0, -0.56);
  g.bezierCurveTo(0.15, -0.7, 0.55, -0.74, 0.72, -0.42);
  g.bezierCurveTo(0.95, 0.05, 0.55, 0.62, 0, 1.0); g.fill();
  g.fillStyle = 'rgba(255,226,150,0.95)';
  const seeds = [[-0.38, -0.22], [0.0, -0.2], [0.38, -0.22], [-0.2, 0.1], [0.2, 0.1], [-0.42, 0.14], [0.42, 0.14], [0, 0.38], [-0.24, 0.42], [0.24, 0.42], [0, 0.68]];
  for (const [sx, sy] of seeds) { g.beginPath(); g.ellipse(sx, sy, 0.045, 0.075, 0, 0, TAU); g.fill(); }
  g.fillStyle = '#3f8f45';
  for (let k = -2; k <= 2; k++) {
    g.save(); g.translate(0, -0.55); g.rotate(k * 0.55);
    g.beginPath(); g.moveTo(0, 0.05); g.quadraticCurveTo(-0.16, -0.2, 0, -0.48); g.quadraticCurveTo(0.16, -0.2, 0, 0.05); g.fill(); g.restore();
  }
  g.restore();
}

function strawberryField(g, W, H, base, seed, tone, alpha = 1) {
  g.fillStyle = base; g.fillRect(0, 0, W, H);
  const r = rng(seed); g.globalAlpha = alpha;
  const step = 132;
  for (let j = -1; j * step < H + step; j++) for (let i = -1; i * step < W + step; i++) {
    const x = i * step + ((j & 1) ? step / 2 : 0) + (r() - 0.5) * 22, y = j * step * 0.82 + (r() - 0.5) * 20;
    strawberry(g, x, y, 27 + r() * 6, (r() - 0.5) * 0.9, tone);
  }
  g.globalAlpha = 1;
}

// shirt layout: grid 16x10 cells (0.72m x 0.45m). top 3 rows = sleeves+shoulders, body cols 4..12
export const SHIRT = { nx: 17, ny: 11, cell: 0.04, b0: 4, b1: 12, sleeveRows: 3 };
function shirtOutline(g, W, H, neck = true) {
  const cx = W / SHIRT.nx * 0, u = W / 16, v = H / 10;
  g.beginPath();
  g.moveTo(0.15 * u, 0.5 * v);                 // left cuff top
  g.lineTo(4.4 * u, 0.02 * v);                   // shoulder
  if (neck) { g.lineTo(6.5 * u, 0.02 * v); g.quadraticCurveTo(8 * u, 1.45 * v, 9.5 * u, 0.02 * v); }
  g.lineTo(11.6 * u, 0.02 * v);
  g.lineTo(15.85 * u, 0.5 * v);                  // right cuff top
  g.lineTo(15.95 * u, 2.9 * v);                  // right cuff bottom
  g.lineTo(12.0 * u, 2.98 * v);                  // armpit
  g.quadraticCurveTo(11.8 * u, 6 * v, 11.97 * u, 9.95 * v);
  g.lineTo(4.03 * u, 9.95 * v);
  g.quadraticCurveTo(4.2 * u, 6 * v, 4.0 * u, 2.98 * v);
  g.lineTo(0.05 * u, 2.9 * v);
  g.closePath();
  return cx;
}
export function shirtTextures() {
  const W = 1024, H = 640, u = W / 16, v = H / 10;
  const mk = (back) => {
    const c = cv(W, H), g = c.getContext('2d');
    g.save(); shirtOutline(g, W, H, true); g.clip();
    if (!back) strawberryField(g, W, H, '#fbf3ea', 7, 1);
    else { strawberryField(g, W, H, '#f6eee6', 7, 1, 0.16); }
    // trims: collar rib, cuffs, hem
    const trim = back ? '#eadfd6' : '#d94a52';
    g.strokeStyle = trim; g.lineWidth = v * 0.34; g.beginPath();
    g.moveTo(6.5 * u, 0.02 * v); g.quadraticCurveTo(8 * u, 1.45 * v, 9.5 * u, 0.02 * v); g.stroke();
    g.fillStyle = trim; g.fillRect(0, 0.3 * v, 0.42 * u, 2.8 * v); g.fillRect(15.58 * u, 0.3 * v, 0.5 * u, 2.8 * v);
    // stitching
    g.strokeStyle = back ? 'rgba(150,130,120,0.55)' : 'rgba(120,90,80,0.35)'; g.lineWidth = 1.5; g.setLineDash([5, 4]);
    g.beginPath(); g.moveTo(4.0 * u, 9.55 * v); g.lineTo(12 * u, 9.55 * v); g.stroke();
    g.beginPath(); g.moveTo(4.3 * u, 0.1 * v); g.quadraticCurveTo(3.9 * u, 1.6 * v, 4.02 * u, 2.98 * v); g.stroke();
    g.beginPath(); g.moveTo(11.7 * u, 0.1 * v); g.quadraticCurveTo(12.1 * u, 1.6 * v, 11.98 * u, 2.98 * v); g.stroke();
    if (back) { g.setLineDash([]); g.strokeStyle = 'rgba(160,140,130,0.5)'; g.lineWidth = 3; g.beginPath(); g.moveTo(4.1 * u, 3 * v); g.lineTo(4.1 * u, 9.9 * v); g.moveTo(11.9 * u, 3 * v); g.lineTo(11.9 * u, 9.9 * v); g.stroke();
      // care label (plain, no text)
      g.fillStyle = '#ffffff'; g.fillRect(7.55 * u, 1.0 * v, 0.9 * u, 0.5 * v); }
    g.setLineDash([]);
    // soft fold shading
    const sh = g.createLinearGradient(0, 0, 0, H); sh.addColorStop(0, 'rgba(0,0,0,0.0)'); sh.addColorStop(1, 'rgba(60,30,20,0.06)');
    g.fillStyle = sh; g.fillRect(0, 0, W, H);
    g.restore();
    grainNoiseAlphaSafe(g, W, H, 0.03, back ? 41 : 40);
    return mkTex(c, { clampEdge: true, aniso: 8 });
  };
  return { front: mk(false), back: mk(true) };
}
function grainNoiseAlphaSafe(g, W, H, a, seed) {
  const im = g.getImageData(0, 0, W, H), d = im.data, r = rng(seed);
  for (let i = 0; i < d.length; i += 4) { if (d[i + 3] === 0) continue; const n = (r() - 0.5) * 255 * a; d[i] = clamp(d[i] + n, 0, 255); d[i + 1] = clamp(d[i + 1] + n, 0, 255); d[i + 2] = clamp(d[i + 2] + n, 0, 255); }
  g.putImageData(im, 0, 0);
}

export const TOWEL = { nx: 9, ny: 16, cell: 0.06 };
export function towelTextures() {
  const W = 512, H = 960;
  const mk = (back) => {
    const c = cv(W, H), g = c.getContext('2d');
    g.fillStyle = back ? '#f3efe6' : '#f7f3ea'; g.fillRect(0, 0, W, H);
    const bands = 12, bh = H / bands;
    for (let i = 0; i < bands; i++) {
      if (i % 2 === 0) continue;
      g.fillStyle = back ? '#7da3c4' : '#5b8fbd'; g.fillRect(0, i * bh, W, bh);
      g.fillStyle = 'rgba(255,255,255,0.35)'; g.fillRect(0, i * bh + bh * 0.42, W, bh * 0.07);
    }
    // woven hem bands at both ends
    for (const y0 of [0, H - 34]) { g.fillStyle = back ? '#d9d3c6' : '#e4ddcf'; g.fillRect(0, y0, W, 34); g.fillStyle = 'rgba(90,110,130,0.35)'; g.fillRect(0, y0 + (y0 ? 3 : 27), W, 4); }
    g.fillStyle = 'rgba(0,0,0,0.05)'; g.fillRect(0, 0, 5, H); g.fillRect(W - 5, 0, 5, H);
    grainNoise(g, W, H, 0.06, back ? 51 : 50);
    return mkTex(c, { clampEdge: true, aniso: 8 });
  };
  return { front: mk(false), back: mk(true) };
}

export const SOCK = { nx: 3, ny: 6, cell: 0.042 };
export function sockTextures() {
  const W = 128, H = 320;
  const mk = (inside) => {
    const c = cv(W, H), g = c.getContext('2d');
    g.beginPath(); g.moveTo(6, 2); g.lineTo(W - 6, 2); g.lineTo(W - 4, H - 60);
    g.quadraticCurveTo(W - 4, H - 3, W / 2, H - 3); g.quadraticCurveTo(4, H - 3, 4, H - 60); g.closePath();
    g.save(); g.clip();
    g.fillStyle = inside ? '#f1e6c4' : '#efc24a'; g.fillRect(0, 0, W, H);
    if (!inside) {
      g.fillStyle = '#fbf6ea'; g.fillRect(0, 0, W, 46);                       // cuff
      g.beginPath(); g.ellipse(W / 2, H - 6, W * 0.62, 50, 0, 0, TAU); g.fill();   // toe
      g.beginPath(); g.ellipse(W * 0.98, H * 0.56, 30, 40, 0, 0, TAU); g.fill();  // heel
      g.strokeStyle = 'rgba(160,120,30,0.25)'; g.lineWidth = 2;
      for (let x = 8; x < W; x += 10) { g.beginPath(); g.moveTo(x, 0); g.lineTo(x, 46); g.stroke(); }
    } else {
      // inside-out: fuzzy pale loops, visible toe seam, loose thread ends
      g.strokeStyle = 'rgba(200,170,90,0.5)'; g.lineWidth = 1;
      const r = rng(77);
      for (let i = 0; i < 500; i++) { const x = r() * W, y = r() * H; g.beginPath(); g.arc(x, y, 2 + r() * 2, 0, Math.PI); g.stroke(); }
      g.strokeStyle = '#c9a23e'; g.lineWidth = 5; g.beginPath(); g.moveTo(10, H - 46); g.quadraticCurveTo(W / 2, H - 22, W - 10, H - 46); g.stroke();
      g.fillStyle = '#e7d7a8'; g.fillRect(0, 0, W, 46);
    }
    g.restore();
    grainNoiseAlphaSafe(g, W, H, 0.05, inside ? 61 : 60);
    return mkTex(c, { clampEdge: true });
  };
  return { out: mk(false), inside: mk(true) };
}

// ---------- hard surfaces ----------
export function drumTextures() {
  const S = 512, c = cv(S, S), g = c.getContext('2d');
  g.fillStyle = '#c9ccce'; g.fillRect(0, 0, S, S);
  const hc = cv(S, S), hg = hc.getContext('2d'); hg.fillStyle = '#808080'; hg.fillRect(0, 0, S, S);
  const n = 16, st = S / n;
  for (let j = 0; j < n; j++) for (let i = 0; i < n; i++) {
    const x = i * st + ((j & 1) ? st / 2 : 0), y = j * st + st / 2;
    for (const dx of [0, -S, S]) {
      const gr = hg.createRadialGradient(x + dx, y, 1, x + dx, y, st * 0.42);
      gr.addColorStop(0, '#000'); gr.addColorStop(0.3, '#202020'); gr.addColorStop(0.55, '#b0b0b0'); gr.addColorStop(1, '#808080');
      hg.fillStyle = gr; hg.beginPath(); hg.arc(x + dx, y, st * 0.42, 0, TAU); hg.fill();
      g.fillStyle = '#17191b'; g.beginPath(); g.arc(x + dx, y, st * 0.13, 0, TAU); g.fill();
    }
  }
  // brushed streaks
  const r = rng(3);
  for (let i = 0; i < 900; i++) { g.strokeStyle = `rgba(${r() < 0.5 ? '255,255,255' : '60,60,70'},${0.03 + r() * 0.04})`; const y = r() * S; g.beginPath(); g.moveTo(0, y); g.lineTo(S, y); g.stroke(); }
  const hd = hg.getImageData(0, 0, S, S).data;
  const nrm = normalFrom(S, S, (x, y) => hd[(y * S + x) * 4] / 255, 2.5);
  return { map: mkTex(c, { repeat: [6, 2] }), normalMap: mkTex(nrm, { data: true, repeat: [6, 2] }) };
}

export function brushedTex() {
  const S = 256, c = cv(S, S), g = c.getContext('2d'), r = rng(8);
  g.fillStyle = '#bfc2c5'; g.fillRect(0, 0, S, S);
  for (let i = 0; i < 1400; i++) { g.strokeStyle = `rgba(${r() < 0.5 ? '255,255,255' : '40,40,50'},${0.04 + r() * 0.06})`; const y = r() * S; g.beginPath(); g.moveTo(0, y); g.lineTo(S, y); g.stroke(); }
  return mkTex(c);
}

export function deckTextures() {
  const t = woodPlanks({ seed: 23, rows: 7, base: [150, 128, 104], repeat: [3, 3] });
  return t;
}

export function sidingTextures() {
  const W = 256, H = 256, c = cv(W, H), g = c.getContext('2d');
  g.fillStyle = '#ece6da'; g.fillRect(0, 0, W, H);
  const rows = 4, rh = H / rows;
  for (let i = 0; i < rows; i++) {
    const gr = g.createLinearGradient(0, i * rh, 0, (i + 1) * rh);
    gr.addColorStop(0, 'rgba(255,255,255,0.25)'); gr.addColorStop(0.85, 'rgba(0,0,0,0.0)'); gr.addColorStop(0.93, 'rgba(60,50,40,0.35)'); gr.addColorStop(1, 'rgba(60,50,40,0.5)');
    g.fillStyle = gr; g.fillRect(0, i * rh, W, rh);
  }
  grainNoise(g, W, H, 0.035, 71);
  const nrm = normalFrom(W, H, (x, y) => { const f = (y % rh) / rh; return (f < 0.9 ? f * 0.6 : (1 - f) * 6) + vnoise(x / 4, y / 4, W / 4, 2) * 0.08; }, 2.5);
  return { map: mkTex(c), normalMap: mkTex(nrm, { data: true }) };
}

export function tileTextures() { // balcony floor: large anti-slip tiles
  const S = 512, c = cv(S, S), g = c.getContext('2d');
  g.fillStyle = '#b9b2a6'; g.fillRect(0, 0, S, S);
  const im = g.getImageData(0, 0, S, S), d = im.data;
  for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) {
    const n = fbm(x / 40, y / 40, S / 40, 4, 91) - 0.5, m = vnoise(x / 2, y / 2, S / 2, 92) - 0.5;
    const i = (y * S + x) * 4, k = n * 46 + m * 16;
    d[i] = clamp(d[i] + k, 0, 255); d[i + 1] = clamp(d[i + 1] + k, 0, 255); d[i + 2] = clamp(d[i + 2] + k * 0.9, 0, 255);
  }
  g.putImageData(im, 0, 0);
  g.fillStyle = '#8d877d'; g.fillRect(0, 0, S, 4); g.fillRect(0, 0, 4, S); g.fillRect(S / 2 - 2, 0, 4, S); g.fillRect(0, S / 2 - 2, S, 4);
  const nrm = normalFrom(S, S, (x, y) => {
    const gx = Math.min(x % (S / 2), S / 2 - (x % (S / 2))), gy = Math.min(y % (S / 2), S / 2 - (y % (S / 2)));
    return Math.min(1, Math.min(gx, gy) / 5) * 0.8 + vnoise(x / 3, y / 3, S / 3, 93) * 0.25;
  }, 2);
  return { map: mkTex(c, { aniso: 8 }), normalMap: mkTex(nrm, { data: true, aniso: 8 }) };
}

// soft round contact shadow
export function blobTex() {
  const S = 128, c = cv(S, S), g = c.getContext('2d');
  const gr = g.createRadialGradient(S / 2, S / 2, 4, S / 2, S / 2, S / 2);
  gr.addColorStop(0, 'rgba(0,0,0,0.7)'); gr.addColorStop(0.6, 'rgba(0,0,0,0.42)'); gr.addColorStop(0.82, 'rgba(0,0,0,0.14)'); gr.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = gr; g.fillRect(0, 0, S, S);
  return mkTex(c, { clampEdge: true });
}

// sky dome (equirect-like: u around, v up) with soft clouds
export function skyCanvas() {
  const W = 1024, H = 512, c = cv(W, H), g = c.getContext('2d');
  const gr = g.createLinearGradient(0, 0, 0, H);
  gr.addColorStop(0, '#4f8fd6'); gr.addColorStop(0.42, '#8fc0ee'); gr.addColorStop(0.62, '#d8eaf6'); gr.addColorStop(0.7, '#eef3f2'); gr.addColorStop(1, '#e6e8e2');
  g.fillStyle = gr; g.fillRect(0, 0, W, H);
  const im = g.getImageData(0, 0, W, H), d = im.data;
  for (let y = 0; y < H * 0.68; y++) for (let x = 0; x < W; x++) {
    const n = fbm(x / 128, y / 46, W / 128, 5, 101);
    const a = clamp((n - 0.52) * 4.2, 0, 1) * clamp(y / (H * 0.2), 0.25, 1) * clamp((H * 0.66 - y) / (H * 0.14), 0, 1);
    const i = (y * W + x) * 4;
    d[i] = d[i] + (255 - d[i]) * a; d[i + 1] = d[i + 1] + (255 - d[i + 1]) * a; d[i + 2] = d[i + 2] + (255 - d[i + 2]) * a;
  }
  g.putImageData(im, 0, 0);
  return c;
}

// distant trees / roofs strip with alpha (hazy)
export function sceneryCanvas() {
  const W = 2048, H = 256, c = cv(W, H), g = c.getContext('2d'), r = rng(131);
  // far hill
  g.fillStyle = 'rgba(150,176,170,0.9)'; g.beginPath(); g.moveTo(0, H);
  for (let x = 0; x <= W; x += 16) g.lineTo(x, H * 0.55 - fbm(x / 300, 1, W / 300, 3, 5) * 70);
  g.lineTo(W, H); g.fill();
  // roofs
  for (let i = 0; i < 22; i++) {
    const x = r() * W, w = 70 + r() * 120, h = 30 + r() * 46, y = H - h - r() * 26;
    g.fillStyle = `rgb(${225 + r() * 20 | 0},${220 + r() * 18 | 0},${208 + r() * 20 | 0})`; g.fillRect(x, y, w, H - y);
    g.fillStyle = `rgb(${110 + r() * 60 | 0},${96 + r() * 40 | 0},${92 + r() * 30 | 0})`;
    g.beginPath(); g.moveTo(x - 10, y); g.lineTo(x + w * 0.5, y - h * 0.5); g.lineTo(x + w + 10, y); g.fill();
    g.fillStyle = 'rgba(120,150,170,0.6)'; for (let k = 0; k < 2; k++) g.fillRect(x + 12 + k * (w * 0.45), y + 12, w * 0.2, 14);
  }
  // trees
  for (let i = 0; i < 80; i++) {
    const x = r() * W, s = 22 + r() * 44, y = H - s * 0.6 - r() * 14;
    const t = 0.75 + r() * 0.4;
    for (let k = 0; k < 9; k++) { g.fillStyle = `rgba(${70 * t + r() * 30 | 0},${118 * t + r() * 30 | 0},${62 * t | 0},0.95)`; g.beginPath(); g.arc(x + (r() - 0.5) * s, y + (r() - 0.5) * s * 0.7, s * (0.3 + r() * 0.25), 0, TAU); g.fill(); }
  }
  // haze
  const hz = g.createLinearGradient(0, 0, 0, H); hz.addColorStop(0, 'rgba(226,236,240,0.5)'); hz.addColorStop(1, 'rgba(226,236,240,0.18)');
  g.globalCompositeOperation = 'source-atop'; g.fillStyle = hz; g.fillRect(0, 0, W, H);
  g.globalCompositeOperation = 'destination-out'; g.fillStyle = '#000'; g.fillRect(0, 0, W, 3);
  return c;
}

export function hanamaruTex() {
  const S = 512, c = cv(S, S), g = c.getContext('2d');
  g.fillStyle = '#fffdf6'; g.fillRect(0, 0, S, S);
  grainNoise(g, S, S, 0.025, 141);
  g.lineCap = 'round'; g.lineJoin = 'round';
  const red = 'rgba(222,52,48,0.92)';
  const wob = rng(5);
  const stroke = (pts, w) => { g.strokeStyle = red; g.lineWidth = w; g.beginPath(); pts.forEach((p, i) => i ? g.lineTo(p[0], p[1]) : g.moveTo(p[0], p[1])); g.stroke(); };
  // spiral
  const sp = []; for (let t = 0; t < TAU * 2.6; t += 0.08) { const rr = 14 + t * 13.5; sp.push([S / 2 + Math.cos(t - 1.2) * rr + (wob() - 0.5) * 2, S / 2 + 6 + Math.sin(t - 1.2) * rr + (wob() - 0.5) * 2]); }
  stroke(sp, 15);
  // petals
  const pet = []; const R0 = 14 + TAU * 2.6 * 13.5;
  for (let t = 0; t <= TAU * 1.02; t += 0.03) { const rr = R0 + 26 + Math.abs(Math.sin(t * 4)) * 44; pet.push([S / 2 + Math.cos(t + 1.0) * rr, S / 2 + 6 + Math.sin(t + 1.0) * rr]); }
  stroke(pet, 15);
  return mkTex(c, { clampEdge: true, aniso: 8 });
}

// knob top: brushed radial metal with notch
export function knobTex(plain) {
  const S = 256, c = cv(S, S), g = c.getContext('2d'), r = rng(12);
  g.fillStyle = '#c6c8ca'; g.fillRect(0, 0, S, S);
  g.translate(S / 2, S / 2);
  for (let i = 0; i < 900; i++) { const a = r() * TAU; g.strokeStyle = `rgba(${r() < 0.5 ? '255,255,255' : '50,50,60'},${0.05 + r() * 0.08})`; g.beginPath(); g.moveTo(0, 0); g.lineTo(Math.cos(a) * S, Math.sin(a) * S); g.stroke(); }
  if (!plain) { g.fillStyle = '#2b2d30'; g.beginPath(); g.roundRect(-5, -S * 0.46, 10, S * 0.2, 5); g.fill(); }
  else { for (let q = 1; q < 6; q++) { g.strokeStyle = 'rgba(60,60,70,0.25)'; g.lineWidth = 2; g.beginPath(); g.arc(0, 0, q * 21, 0, TAU); g.stroke(); } }
  return mkTex(c, { clampEdge: true });
}

// cardboard-free plain paper normal etc. are done with noiseNormal

// finger sprite for the idle demonstration (2D overlay element)
export function fingerCanvas() {
  const W = 96, H = 150, c = cv(W, H), g = c.getContext('2d');
  const gr = g.createLinearGradient(0, 0, W, 0); gr.addColorStop(0, '#f4c9a8'); gr.addColorStop(0.5, '#fbdcc2'); gr.addColorStop(1, '#e6b392');
  g.fillStyle = gr; g.shadowColor = 'rgba(0,0,0,0.35)'; g.shadowBlur = 10; g.shadowOffsetY = 4;
  g.beginPath(); g.roundRect(26, 8, 44, 150, 22); g.fill();
  g.shadowColor = 'transparent';
  g.fillStyle = 'rgba(255,240,232,0.85)'; g.beginPath(); g.roundRect(34, 14, 28, 30, 12); g.fill();
  g.strokeStyle = 'rgba(190,140,110,0.5)'; g.lineWidth = 1.5; g.beginPath(); g.moveTo(34, 78); g.quadraticCurveTo(48, 83, 62, 78); g.moveTo(35, 86); g.quadraticCurveTo(48, 90, 61, 86); g.stroke();
  return c;
}

// soft reflection of a bright window on curved glass
export function glintTex() {
  const S = 256, c = cv(S, S), g = c.getContext('2d');
  g.save(); g.beginPath(); g.arc(S / 2, S / 2, S * 0.5, 0, TAU); g.clip();
  const gr = g.createLinearGradient(S * 0.15, S * 0.1, S * 0.6, S * 0.7); gr.addColorStop(0, 'rgba(255,255,255,0.85)'); gr.addColorStop(0.35, 'rgba(255,255,255,0.22)'); gr.addColorStop(0.6, 'rgba(255,255,255,0)');
  g.fillStyle = gr; g.beginPath(); g.ellipse(S * 0.34, S * 0.33, S * 0.2, S * 0.3, 0.7, 0, TAU); g.fill();
  g.globalCompositeOperation = 'destination-out'; g.beginPath(); g.ellipse(S * 0.43, S * 0.43, S * 0.2, S * 0.3, 0.7, 0, TAU); g.fill();
  g.globalCompositeOperation = 'source-over'; g.strokeStyle = 'rgba(255,255,255,0.28)'; g.lineWidth = 5; g.beginPath(); g.arc(S / 2, S / 2, S * 0.44, Math.PI * 0.15, Math.PI * 0.42); g.stroke();
  g.restore();
  return mkTex(c, { clampEdge: true });
}
